 "content": "def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 2]
    # The two points sharing a row form the horizontal spine.
    by_row = {}
    for r, c in points:
        by_row.setdefault(r, []).append(c)
    spine_row, spine_cols = next((r, cols) for r, cols in by_row.items() if len(cols) >= 2)
    left, right = min(spine_cols), max(spine_cols)
    for c in range(left + 1, right):
        out[spine_row][c] = 3
    # Connect each remaining marker vertically to the spine.
    for r, c in points:
        if r == spine_row:
            continue
        lo, hi = sorted((r, spine_row))
        for rr in range(lo + 1, hi):
            out[rr][c] = 3
    return out

